#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);
    vector<pair<int,int>> ops;
    auto apply=[&](int x,int y){
        assert(x>=1&&y>=1&&x+y<=n-1);
        ops.push_back({x,y});
        vector<int> np(n);
        for(int i=0;i<y;i++) np[i]=p[n-y+i];
        for(int i=0;i<n-x-y;i++) np[y+i]=p[x+i];
        for(int i=0;i<x;i++) np[n-x+i]=p[i];
        p=np;
    };
    for(int t=0;t<n;t++){
        int pos=-1;
        for(int i=t;i<n;i++) if(p[i]==t+1){pos=i;break;}
        if(pos==t) continue;
        // Move element at pos to position t
        // Step 1: move to position 0
        if(pos>0){
            int y=n-pos;
            int x=1;
            if(x+y<=n-1){
                apply(x,y); // element at pos -> position 0
            } else {
                // pos=1, y=n-1, x=1, x+y=n. Need different approach.
                // Use x=2,y=n-2: element at pos=1 goes to middle start = y = n-2. 
                if(n>=4){apply(2,n-3);} // element at 1: in prefix(0..1)->goes to end(n-2..n-1), specifically n-1
                // now at n-1, bring to 0
                if(n>=3) apply(1,1); // element at n-1 -> position 0
            }
            for(int i=0;i<n;i++) if(p[i]==t+1){pos=i;break;}
        }
        if(pos==t) continue;
        // Element should be at position 0 now (pos=0)
        if(pos==0 && t>0){
            // (x, y): element at 0 goes to position n-x. We want n-x=t => x=n-t.
            int x=n-t, y=1;
            if(x>=1&&y>=1&&x+y<=n-1){
                apply(x,y);
            } else {
                // x+y=n-t+1>n-1 => t<2. t=1: x=n-1,y=1,x+y=n. Use y=2 if possible? Hmm
                if(t==1&&n>=4){apply(n-2,1);apply(1,1);}
                else if(t==1&&n==3){apply(1,1);}
            }
        }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
